using System.Data;
using Microsoft.Data.SqlClient;
using TransPort.Api.Configuration;
using TransPort.Api.Modules.Alertas.DTOs;
using TransPort.Api.Modules.Shared.DTOs;
using TransPort.Api.Modules.Shared.Repositories;

namespace TransPort.Api.Modules.Alertas.Repositories;

public sealed class AlertaRepository(ISqlConnectionFactory connections):IAlertaRepository
{
    public async Task<IReadOnlyList<AlertaListadoDto>> ListarAsync(string? estado,bool soloPendientes,AlcanceAlerta a,CancellationToken ct){var items=new List<AlertaListadoDto>();await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=Proc(cn,"sp_alertas_leer_listado");Scope(c,a);Text(c,"@Estado",20,estado);c.Parameters.Add("@SoloPendientes",SqlDbType.Bit).Value=soloPendientes;await using var r=await c.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))items.Add(new(r.Int64("AlertaNotificacionId"),r.Text("Tipo"),r.Text("Titulo"),r.Text("Mensaje"),r.Text("Severidad"),r.Text("Estado"),r.Date("FechaProgramadaUtc"),r.NullableDate("FechaVencimientoUtc"),r.NullableText("Rol"),r.NullableText("Giro"),r.NullableText("Sede"),r.NullableText("UsuarioDestino"),r.NullableText("ModuloOrigen"),Long(r,"RegistroOrigenId"),r.GetBoolean(r.GetOrdinal("Leida")),r.Int32("Seguimientos")));return items;}
    public async Task<AlertaDetalleDto?> ObtenerAsync(long id,AlcanceAlerta a,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=Proc(cn,"sp_alertas_leer_por_id");c.Parameters.Add("@Id",SqlDbType.BigInt).Value=id;Scope(c,a);await using var r=await c.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))return null;var x=new AlertaDetalleDto(r.Int64("AlertaNotificacionId"),r.Text("Tipo"),r.Text("Titulo"),r.Text("Mensaje"),r.Text("Severidad"),r.Text("Estado"),r.Date("FechaProgramadaUtc"),r.NullableDate("FechaVencimientoUtc"),Int(r,"RolId"),r.NullableText("Rol"),Int(r,"GiroNegocioId"),r.NullableText("Giro"),Int(r,"SedeId"),r.NullableText("Sede"),Int(r,"UsuarioDestinoId"),r.NullableText("UsuarioDestino"),r.NullableText("ModuloOrigen"),Long(r,"RegistroOrigenId"),r.Text("CreadoPor"),r.Date("FechaCreacion"),r.GetBoolean(r.GetOrdinal("Leida")),r.NullableDate("FechaLectura"),[]);var seg=new List<AlertaSeguimientoDto>();if(await r.NextResultAsync(ct))while(await r.ReadAsync(ct))seg.Add(new(r.Int64("AlertaSeguimientoId"),r.Text("Comentario"),r.Text("NombreUsuario"),r.Date("Fecha")));return x with{Seguimientos=seg};}
    public async Task<AlertaOpcionesDto> OpcionesAsync(AlcanceAlerta a,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=Proc(cn,"sp_alertas_leer_opciones");Scope(c,a);await using var r=await c.ExecuteReaderAsync(ct);var roles=await Cats(r,ct);var giros=await Next(r,ct);var sedes=await Next(r,ct);var users=await Next(r,ct);return new(roles,giros,sedes,users);}
    public Task<long> CrearAsync(CrearAlertaRequest x,AlcanceAlerta a,CancellationToken ct)=>Scalar("sp_alertas_crear",a,ct,c=>{Text(c,"@Tipo",20,x.Tipo);Text(c,"@Titulo",180,x.Titulo);Text(c,"@Mensaje",1500,x.Mensaje);Text(c,"@Severidad",20,x.Severidad);c.Parameters.Add("@RolId",SqlDbType.Int).Value=Db(x.RolId);c.Parameters.Add("@GiroId",SqlDbType.Int).Value=Db(x.GiroId);c.Parameters.Add("@SedeId",SqlDbType.Int).Value=Db(x.SedeId);c.Parameters.Add("@UsuarioDestinoId",SqlDbType.Int).Value=Db(x.UsuarioDestinoId);c.Parameters.Add("@FechaProgramadaUtc",SqlDbType.DateTime2).Value=x.FechaProgramadaUtc;c.Parameters.Add("@FechaVencimientoUtc",SqlDbType.DateTime2).Value=Db(x.FechaVencimientoUtc);Text(c,"@ModuloOrigen",50,x.ModuloOrigen);c.Parameters.Add("@RegistroOrigenId",SqlDbType.BigInt).Value=Db(x.RegistroOrigenId);});
    public async Task<bool> MarcarLeidaAsync(long id,AlcanceAlerta a,CancellationToken ct)=>await Bool("sp_alertas_marcar_leida",id,null,a,ct);
    public Task<long> SeguimientoAsync(long id,string comentario,AlcanceAlerta a,CancellationToken ct)=>Scalar("sp_alertas_agregar_seguimiento",a,ct,c=>{c.Parameters.Add("@Id",SqlDbType.BigInt).Value=id;Text(c,"@Comentario",1000,comentario);});
    public async Task<bool> EstadoAsync(long id,string estado,AlcanceAlerta a,CancellationToken ct)=>await Bool("sp_alertas_actualizar_estado",id,estado,a,ct);
    public async Task<bool> EliminarAsync(long id,int usuarioId,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=Proc(cn,"sp_alertas_eliminar");c.Parameters.Add("@Id",SqlDbType.BigInt).Value=id;c.Parameters.Add("@UsuarioId",SqlDbType.Int).Value=usuarioId;return Convert.ToInt32(await c.ExecuteScalarAsync(ct))>0;}
    private async Task<bool> Bool(string proc,long id,string? estado,AlcanceAlerta a,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=Proc(cn,proc);c.Parameters.Add("@Id",SqlDbType.BigInt).Value=id;if(estado is not null)Text(c,"@Estado",20,estado);Scope(c,a);return Convert.ToInt32(await c.ExecuteScalarAsync(ct))>0;}
    private async Task<long> Scalar(string proc,AlcanceAlerta a,CancellationToken ct,Action<SqlCommand> add){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=Proc(cn,proc);add(c);Scope(c,a);return Convert.ToInt64(await c.ExecuteScalarAsync(ct));}
    private static async Task<IReadOnlyList<CatalogoDto>> Next(SqlDataReader r,CancellationToken ct)=>await r.NextResultAsync(ct)?await Cats(r,ct):[];private static async Task<IReadOnlyList<CatalogoDto>> Cats(SqlDataReader r,CancellationToken ct){var x=new List<CatalogoDto>();while(await r.ReadAsync(ct))x.Add(new(r.Int32("Id"),r.Text("Nombre")));return x;}
    private static SqlCommand Proc(SqlConnection cn,string n)=>new(n,cn){CommandType=CommandType.StoredProcedure};private static void Scope(SqlCommand c,AlcanceAlerta a){c.Parameters.Add("@UsuarioId",SqlDbType.Int).Value=a.UsuarioId;c.Parameters.Add("@EsAdministrador",SqlDbType.Bit).Value=a.EsAdministrador;}private static object Db(object? x)=>x??DBNull.Value;private static void Text(SqlCommand c,string n,int z,string? x)=>c.Parameters.Add(n,SqlDbType.NVarChar,z).Value=Db(string.IsNullOrWhiteSpace(x)?null:x.Trim());private static int? Int(SqlDataReader r,string n){var i=r.GetOrdinal(n);return r.IsDBNull(i)?null:r.GetInt32(i);}private static long? Long(SqlDataReader r,string n){var i=r.GetOrdinal(n);return r.IsDBNull(i)?null:r.GetInt64(i);}
}
